PROGRAM alarm_ctrl
VAR_INPUT
    Trip : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Alarm : BOOL;
END_VAR
VAR
    AlarmLatch : BOOL;
END_VAR

IF Trip THEN
    AlarmLatch := TRUE;
ELSIF Reset AND NOT Trip THEN
    AlarmLatch := FALSE;
END_IF;

Alarm := AlarmLatch;
END_PROGRAM

PROGRAM alarm_ctrl
VAR_INPUT
