PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        0: // Idle
            IF EStop OR NOT StartBatch THEN
                State := 0;
            ELSIF Level < LVL_HIGH THEN
                State := 1;
            END_IF;
        1: // Fill
            FillValve := TRUE;
            IF Level >= LVL_HIGH THEN
                State := 2;
            ELSIF NOT EStop THEN
                State := 0;
            END_IF;
        2: // Heat
            Heater := TRUE;
            Agitator := TRUE;
            IF Temp >= TEMP_SET THEN
                State := 3;
            ELSIF NOT EStop THEN
                State := 0;
            END_IF;
        3: // React
            Heater := TRUE;
            Agitator := TRUE;
            IF T#3s <= PT_REACT THEN
                State := 4;
            ELSIF NOT EStop THEN
                State := 0;
            END_IF;
        4: // Drain
            DrainValve := TRUE;
            IF Level <= LVL_LOW THEN
                State := 0;
            ELSIF NOT EStop THEN
                State := 0;
            END_IF;
    END_CASE;
END_IF;

FillValve := (State = 1);
Heater := (State = 2) OR (State = 3);
Agitator := (State = 2) OR (State = 3);
DrainValve := (State = 4);

END_PROGRAM

