END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        0: -- Idle
            IF Level < LVL_HIGH THEN
                State := 1;
            END_IF;

        1: -- Fill
            FillValve := TRUE;
            IF Level >= LVL_HIGH THEN
                State := 2;
            END_IF;

        2: -- Heat
            Heater := TRUE;
            Agitator := TRUE;
            IF Temp >= TEMP_SET THEN
                State := 3;
            END_IF;

        3: -- React
            Heater := TRUE;
            Agitator := TRUE;
            IF NOT PT_REACT.TON_Q THEN
                PT_REACT(IN := TRUE, PT := PT_REACT);
            ELSE
                State := 4;
            END_IF;

        4: -- Drain
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
            IF Level <= LVL_LOW THEN
                State := 0;
            END_IF;
    END_CASE;
END_IF;

-- Safety conditions
FillValve AND DrainValve => FALSE;
NOT EStop AND (Heater OR Agitator) AND (Level < LIQ_MIN) => FALSE;

