PROGRAM star_delta
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    MainK : BOOL;
    StarK : BOOL;
    DeltaK : BOOL;
END_VAR
VAR CONSTANT
    PT_STAR : TIME := T#3s;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0: // Off
        IF StartPB AND EStop THEN
            State := 1;
            MainK := TRUE;
            StarK := TRUE;
            DeltaK := FALSE;
        END_IF;

    1: // Star
        IF NOT EStop OR StopPB THEN
            State := 0;
            MainK := FALSE;
            StarK := FALSE;
            DeltaK := FALSE;
        ELSIF PT_STAR <= T#0s THEN
            State := 2;
            StarK := FALSE;
            DeltaK := TRUE;
        ELSE
            PT_STAR(IN := TRUE, PT := PT_STAR);
        END_IF;

    2: // Delta
        IF NOT EStop OR StopPB THEN
            State := 0;
            MainK := FALSE;
            StarK := FALSE;
            DeltaK := FALSE;
        END_IF;
END_CASE;

END_PROGRAM

