PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0: -- Idle
            Pump := FALSE;
            Valve := FALSE;
            IF StartCycle AND Level < 90 THEN
                State := 1;
            END_IF;

        1: -- Filling
            Pump := TRUE;
            Valve := FALSE;
            IF Level >= 90 THEN
                State := 2;
            END_IF;

        2: -- Draining
            Pump := FALSE;
            Valve := TRUE;
            IF Level <= 10 THEN
                State := 0;
            END_IF;
    END_CASE;
ELSE
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
END_IF;

END_PROGRAM

