    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

IF EStop THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
ELSIF NOT EStop THEN
    CASE State OF
        0:  // Idle
            IF StartCycle AND Level < 90 THEN
                State := 1;
                Pump := TRUE;
                Valve := FALSE;
            ELSE
                Pump := FALSE;
                Valve := FALSE;
            END_IF;

        1:  // Filling
            IF Level >= 90 THEN
                State := 2;
                Pump := FALSE;
                Valve := TRUE;
            END_IF;

        2:  // Draining
            IF Level <= 10 THEN
                State := 0;
                Pump := FALSE;
                Valve := FALSE;
            END_IF;
    END_CASE;
END_IF;

// Safety conditions
ASSERT(not(Pump and Valve));
ASSERT(Level < 90 or not(Pump));
ASSERT(Level > 10 or not(Valve));

END_PROGRAM

