    StopPB : BOOL;
    EStop : BOOL;
    Flame : BOOL;
END_VAR
VAR_OUTPUT
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR
VAR CONSTANT
    PT_PURGE : TIME := T#3s;
    PT_IGN : TIME := T#2s;
END_VAR
VAR
    State : INT := 0;
END_VAR
CASE State OF
    0: // Off
        IF StartPB AND NOT EStop THEN
            State := 1;
        END_IF;
    1: // Purge
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF TON(IN := TRUE, PT := PT_PURGE).Q THEN
            State := 2;
        END_IF;
    2: // Ignition trial
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF TON(IN := TRUE, PT := PT_IGN).Q THEN
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;
    3: // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

