        IF OpenLimit THEN
            State := 0;
        ELSIF Obstruction THEN
            State := 0;
        END_IF;

    2: -- Closing
        MotorOpen := FALSE;
        MotorClose := TRUE;
        IF CloseLimit OR Obstruction THEN
            State := 0;
        END_IF;
END_CASE;

