PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
    TSeq_C3 : TON;
    TSeq_C2 : TON;
END_VAR

IF NOT EStop OR StopPB THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
ELSIF StartPB AND State = 0 THEN
    State := 1;
    TSeq_C3(IN := TRUE, PT := T#2s);
    C1 := FALSE;
    C2 := FALSE;
    C3 := TRUE;
ELSIF TSeq_C3.Q AND State = 1 THEN
    State := 2;
    TSeq_C2(IN := TRUE, PT := T#2s);
    C1 := FALSE;
    C2 := TRUE;
    C3 := TRUE;
ELSIF TSeq_C2.Q AND State = 2 THEN
    State := 3;
    C1 := TRUE;
    C2 := TRUE;
    C3 := TRUE;
END_IF;

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
END_CASE;

TSeq_C3(IN := FALSE, PT := T#0s);
TSeq_C2(IN := FALSE, PT := T#0s);

END_PROGRAM

