VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

IF NOT EStop OR StopPB THEN
    State := 0;
ELSIF StartPB AND State = 0 THEN
    State := 1;
ELSIF State = 1 AND Ticks >= 2 THEN
    State := 2;
ELSIF State = 2 AND Ticks >= 4 THEN
    State := 3;
END_IF;

CASE State OF
    0: C1 := FALSE; C2 := FALSE; C3 := FALSE;
    1: C1 := FALSE; C2 := FALSE; C3 := TRUE;
    2: C1 := FALSE; C2 := TRUE; C3 := TRUE;
    3: C1 := TRUE; C2 := TRUE; C3 := TRUE;
END_CASE;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0:
            IF StartPB AND NOT StopPB THEN
                State := 1;
            END_IF;
        1:
            IF StartPB AND NOT StopPB AND NOT C3 THEN
                State := 1;
            ELSIF StartPB AND NOT StopPB AND C3 AND NOT C2 THEN
                State := 2;
                T1(IN := TRUE, PT := PT_SEQ);
            ELSIF StartPB AND NOT StopPB AND C3 AND C2 AND NOT C1 THEN
                State := 3;
                T2(IN := TRUE, PT := PT_SEQ);
            END_IF;
        2:
            IF StartPB AND NOT StopPB AND C3 AND NOT C2 THEN
                State := 2;
            ELSIF StartPB AND NOT StopPB AND C3 AND C2 AND NOT C1 THEN
                State := 3;
                T2(IN := TRUE, PT := PT_SEQ);
            END_IF;
        3:
            IF StartPB AND NOT StopPB AND C3 AND C2 AND C1 THEN
                State := 3;
                T2(IN := TRUE, PT := PT_SEQ);
            END_IF;
    END_CASE;

    C1 := (State >= 3) AND T2.Q;
    C2 := (State >= 2) AND T1.Q;
    C3 := State > 0;
ELSE
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
    State := 0;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
    T_C3 : TON;
    T_C2 : TON;
END_VAR

T_C3(IN := NOT EStop AND NOT StopPB AND (State = 1 OR State = 2 OR State = 3));
T_C2(IN := NOT EStop AND NOT StopPB AND (State = 2 OR State = 3));

IF StartPB AND NOT StopPB AND EStop THEN
    State := 0;
ELSIF StopPB OR NOT EStop THEN
    State := 0;
ELSIF State = 0 AND T_C3.Q AND T_C2.Q THEN
    State := 1;
ELSIF State = 1 AND T_C2.Q THEN
    State := 2;
ELSIF State = 2 THEN
    State := 3;
END_IF;

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
END_CASE;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

CASE State OF
    0: // Off
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;

    1: // C3
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;

    2: // C3 + C2
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;

    3: // All
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
END_CASE

IF NOT EStop OR StopPB THEN
    State := 0;
ELSIF StartPB AND State = 0 THEN
    State := 1;
ELSIF StartPB AND State = 1 AND TON_C3.Q THEN
    State := 2;
ELSIF StartPB AND State = 2 AND TON_C2.Q THEN
    State := 3;
END_IF

IF State >= 1 THEN
    TON_C3(IN := TRUE, PT := PT_SEQ);
ELSIF State >= 2 THEN
    TON_C2(IN := TRUE, PT := PT_SEQ);
END_IF

END_PROGRAM

